// Белый список разрезов — ровно AUD_DIMS из макета. Поимённых списков нет.
const DIMS = ['lvl3', 'lvl4', 'stream', 'spec', 'exp', 'it', 'hq', 'adgroup'];
const MAX_VALUES = 200;
const item = $input.first().json;
const b = item.body || {};
const headers = item.headers || {};
const fail = (error, detail) => ({ json: { ok: false, status: 400, error, detail } });

if (!['save', 'deactivate'].includes(b.action)) return [fail('bad_action')];
if (!Number.isInteger(b.dashboard_id) || b.dashboard_id <= 0) return [fail('bad_dashboard_id')];
if (typeof b.request_id !== 'string' || b.request_id.length < 8) return [fail('bad_request_id')];
if (!Number.isInteger(b.expected_version) || b.expected_version < 0) return [fail('bad_expected_version')];

const filters = {};
if (b.action === 'save') {
  const f = b.filters || {};
  const unknown = Object.keys(f).filter((k) => !DIMS.includes(k));
  if (unknown.length) return [fail('unknown_dims', unknown)];
  for (const k of DIMS) {
    const v = f[k] || [];
    if (!Array.isArray(v) || v.some((s) => typeof s !== 'string' || !s.trim())) return [fail('bad_values', k)];
    if (v.length > MAX_VALUES) return [fail('too_many_values', k)];
    filters[k] = [...new Set(v.map((s) => s.trim()))].sort();   // канонический вид
  }
  if (!DIMS.some((k) => filters[k].length)) return [fail('no_conditions')];
}

return [{ json: {
  ok: true,
  req: {
    action: b.action, dashboard_id: b.dashboard_id, request_id: b.request_id,
    expected_version: b.expected_version, filters,
    comment: String(b.comment || '').slice(0, 500),
    client: String(b.client || 'proteus_adoption_ui'),
  },
  headers,
  ctx: {},
} }];

/* STUB. Заменить на проверку идентичности (PLAN.md §7.1).
   Вход:  $json.headers
   Выход: ctx.login — логин сотрудника из ПРОВЕРЕННОГО источника.
          Нет/невалидно → ok:false, status:401, error:'unauthenticated'.
   Нельзя: брать логин из тела запроса.
   Мок: читает X-Forwarded-User (как от SSO-прокси), иначе 'a.petrova'. */
const it = $input.first().json;
const login = (it.headers['x-forwarded-user'] || 'a.petrova').toLowerCase();
if (!login) return [{ json: { ok: false, status: 401, error: 'unauthenticated' } }];
return [{ json: { ...it, ctx: { ...it.ctx, login } } }];

/* STUB. Заменить на запрос к метаданным Proteus (API дашборда или таблица
   владельцев в prod_proteus).
   Вход:  req.dashboard_id
   Выход: ctx.owners: string[] (логины, нижний регистр), ctx.dashboard_nm.
          Отчёта нет → ok:false, status:404, error:'report_not_found'.
   Мок: отчёты 14000…15000 существуют, владельцы — a.petrova и d.sokolov. */
const it = $input.first().json;
const id = it.req.dashboard_id;
if (id < 14000 || id > 15000) return [{ json: { ok: false, status: 404, error: 'report_not_found' } }];
return [{ json: { ...it, ctx: { ...it.ctx, owners: ['a.petrova', 'd.sokolov'], dashboard_nm: 'Отчёт ' + id } } }];

// Белый список админов — пока пустой (PLAN.md §7.2).
const ADMINS = [];
const it = $input.first().json;
if (it.ok === false) return [{ json: it }];
const { login, owners } = it.ctx;
if (!owners.includes(login) && !ADMINS.includes(login)) {
  return [{ json: { ok: false, status: 403, error: 'not_owner', detail: { owners } } }];
}
return [{ json: { ...it, ok: true } }];

/* STUB. Заменить на SQL к DLH:
     SELECT version, action, saved_by, saved_at, request_id
     FROM proteus_adoption.ta_event
     WHERE dashboard_id = :id ORDER BY version DESC LIMIT 1;
   плюс поиск того же request_id:
     SELECT version, saved_at FROM proteus_adoption.ta_event WHERE request_id = :rid;
   Выход: ctx.current = {version, action, saved_by, saved_at} | null,
          ctx.replay  = {version, saved_at} | null.
   Мок: у отчёта 14037 уже есть v2 от d.sokolov, у остальных ничего. */
const it = $input.first().json;
const current = it.req.dashboard_id === 14037
  ? { version: 2, action: 'save', saved_by: 'd.sokolov', saved_at: '2026-10-12T09:14:00Z' }
  : null;
return [{ json: { ...it, ctx: { ...it.ctx, current, replay: null } } }];

const it = $input.first().json;
const { current, replay } = it.ctx;
// Идемпотентность: тот же request_id уже записан — отвечаем прежним результатом.
if (replay) return [{ json: { ok: false, status: 200, error: null, body: { ok: true, replay: true, ...replay } } }];
const have = current ? current.version : 0;
if (it.req.expected_version !== have) {
  return [{ json: { ok: false, status: 409, error: 'version_conflict',
    detail: { current_version: have, saved_by: current && current.saved_by, saved_at: current && current.saved_at } } }];
}
if (it.req.action === 'deactivate' && (!current || current.action === 'deactivate')) {
  return [{ json: { ok: false, status: 409, error: 'nothing_to_deactivate' } }];
}
return [{ json: { ...it, ok: true, ctx: { ...it.ctx, next_version: have + 1 } } }];

/* STUB. Заменить на запросы к mdm_employee_daily_proteus (последний report_dt):
   1) какие из переданных кодов существуют по каждому разрезу;
   2) сколько сотрудников попадает под условия (те же предикаты, что
      в PLAN.md §5.1) — audience_cnt;
   3) у скольких из них есть доступ к отчёту — access_cnt;
   4) имена для кодов — labels.
   Для action='deactivate' шаг пропускается (см. первую строку).
   Выход: ctx.audience_cnt, ctx.access_cnt, ctx.labels {код: имя}.
          Неизвестные коды → 422 unknown_values; 0 человек → 422 empty_audience.
   Мок: код, начинающийся с 'X_', считается несуществующим. */
const it = $input.first().json;
if (it.req.action === 'deactivate') return [{ json: { ...it, ctx: { ...it.ctx, audience_cnt: 0, access_cnt: 0, labels: {} } } }];
const f = it.req.filters;
const unknown = {};
Object.keys(f).forEach((k) => { const u = f[k].filter((v) => v.startsWith('X_')); if (u.length) unknown[k] = u; });
if (Object.keys(unknown).length) return [{ json: { ok: false, status: 422, error: 'unknown_values', detail: unknown } }];
const labels = {};
Object.values(f).flat().forEach((v) => { labels[v] = v; });
const audience_cnt = 1240, access_cnt = 1015;
if (!audience_cnt) return [{ json: { ok: false, status: 422, error: 'empty_audience' } }];
return [{ json: { ...it, ok: true, ctx: { ...it.ctx, audience_cnt, access_cnt, labels } } }];

// Ровно схема proteus_adoption.ta_event (PLAN.md §2).
const it = $input.first().json;
const { req, ctx } = it;
const DIMS = ['lvl3', 'lvl4', 'stream', 'spec', 'exp', 'it', 'hq', 'adgroup'];
const f = req.action === 'save' ? req.filters : {};
const row = {
  event_id: $execution.id + '-' + req.request_id,
  request_id: req.request_id,
  dashboard_id: req.dashboard_id,
  action: req.action,
  version: ctx.next_version,
  filters_json: JSON.stringify(Object.fromEntries(DIMS.map((k) => [k, f[k] || []]))),
  labels_json: JSON.stringify(ctx.labels || {}),
  audience_cnt: ctx.audience_cnt,
  access_cnt: ctx.access_cnt,
  comment: req.comment,
  saved_by: ctx.login,            // из проверенной идентичности
  saved_at: new Date().toISOString(),
  client: req.client,
};
DIMS.forEach((k) => { row['f_' + k] = f[k] || []; });
return [{ json: { ...it, row } }];

/* STUB. Заменить на INSERT в proteus_adoption.ta_event.
   Гонка между «Текущая версия» и записью: вставлять условно —
     INSERT ... SELECT ... WHERE (SELECT coalesce(max(version),0)
       FROM ta_event WHERE dashboard_id = :id) = :expected_version
   и если вставилось 0 строк → ok:false, status:409, error:'version_conflict'.
   Ошибка хранилища → ok:false, status:502, error:'storage_failed'.
   Выход: тот же объект, ok:true.
   Мок: всегда успешно. */
const it = $input.first().json;
return [{ json: { ...it, ok: true } }];

/* STUB. Заменить на запуск ноутбука ta_sync через API планировщика
   (PLAN.md §7.5). Ошибка здесь НЕ ломает ответ: запись уже в DLH,
   ноутбук подхватит по расписанию.
   Выход: ctx.sync = 'queued' | 'scheduled'.
   Мок: 'queued'. */
const it = $input.first().json;
let sync = 'queued';
try { /* вызов API */ } catch (e) { sync = 'scheduled'; }
return [{ json: { ...it, ctx: { ...it.ctx, sync } } }];

const it = $input.first().json;
return [{ json: { status: 200, body: {
  ok: true,
  action: it.req.action,
  dashboard_id: it.req.dashboard_id,
  version: it.row.version,
  saved_by: it.row.saved_by,
  saved_at: it.row.saved_at,
  audience_cnt: it.row.audience_cnt,
  access_cnt: it.row.access_cnt,
  sync: it.ctx.sync,
} } }];

// Сюда сходятся все ветки «нет». Внутренности (заголовки, ctx) наружу не отдаём.
const it = $input.first().json;
if (it.body) return [{ json: { status: it.status, body: it.body } }];   // replay
return [{ json: { status: it.status || 500, body: { ok: false, error: it.error || 'internal', detail: it.detail || null } } }];
